    [10720] = {"侏儒撒网器", "装备后绑定\n饰品\n需要 工程学 (210)\n使用: 将目标捕获在网中，持续 20 秒。然而，网有很多钩子，有时在发射时会被使用者的衣服钩住……（10 分钟冷却时间）", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["Trinket"] = "饰品", ["Requires Engineering (210)"] = "需要 工程学 (210)", ["Use: Captures the target in a net for 20 sec. The net has a lot of hooks however and sometimes gets caught in the user's clothing when fired...... (10 Min Cooldown)"] = "使用: 将目标捕获在网中，持续 20 秒。然而，网有很多钩子，有时在发射时会被使用者的衣服钩住……（10 分钟冷却时间）" }, "Gnomish Net-o-Matic Projector"},
    [10721] = {"侏儒防护腰带", "装备后绑定\n腰部 66 护甲 +9 耐力 物品 等级 43。\n需要 工程学 (215)\n使用：力量之盾可以保护你在接下来的 10 分钟内免受接下来的 500 点伤害。警告：当佩戴者暂时脱离此维度时，力场可能会过载。 （1 小时冷却时间）", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["Waist 66 Armor +9 Stamina Item Level 43"] = "腰部 66 护甲 +9 耐力 物品 等级 43。", ["Requires Engineering (215)"] = "需要 工程学 (215)", ["Use: A shield of force protects you from the next 500 damage done over the next 10 min. WARNING: Force Field may overload when struck temporarily removing the wearer from this dimension. (1 Hr Cooldown)"] = "使用：力量之盾可以保护你在接下来的 10 分钟内免受接下来的 500 点伤害。警告：当佩戴者暂时脱离此维度时，力场可能会过载。 （1 小时冷却时间）" }, "Gnomish Harm Prevention Belt"},
    [10722] = {"基姆加尔的烧鸡", "任务物品\n唯一", "EpochHead 消耗品", "consumable", { ["Quest Item"] = "任务物品", ["Unique"] = "唯一" }, "Kim'Jael's Stuffed Chicken"},
    [10724] = {"侏儒火箭靴", "装备后绑定\n脚 41 护甲 物品 等级 45。\n需要 工程学 (225)\n使用: 这些靴子可以显着提高你的奔跑速度，持续 20 秒。警告：它们的电源和陀螺仪并不总是按预期工作。 （30 分钟冷却时间）", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["Feet 41 Armor Item Level 45"] = "脚 41 护甲 物品 等级 45。", ["Requires Engineering (225)"] = "需要 工程学 (225)", ["Use: These boots significantly increase your run speed for 20 sec. WARNING: Their power supply and gyros do not always function as intended. (30 Min Cooldown)"] = "使用: 这些靴子可以显着提高你的奔跑速度，持续 20 秒。警告：它们的电源和陀螺仪并不总是按预期工作。 （30 分钟冷却时间）" }, "Gnomish Rocket Boots"},
