    [12634] = {"凿刻束带", "拾取后绑定\n腰部 199 护甲 +9 耐力 +12 智力。\n需要等级 55\n物品等级 60\n装备：+38 攻击强度", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Waist 199 Armor +9 Stamina +12 Intellect"] = "腰部 199 护甲 +9 耐力 +12 智力。", ["Requires Level 55"] = "需要等级 55", ["Item Level 60"] = "物品等级 60", ["Equip: +38 Attack Power."] = "装备：+38 攻击强度" }, "Chiselbrand Girdle"},
    [12637] = {"班诺克护手", "拾取后绑定\n手 392 护甲 +9 力量 +14 耐力 +9 智力。\n需要等级 55\n物品等级 60\n装备：恢复 4 法力值 per 5秒. Equip: 提高 伤害 done by Holy 法术和effects by最多12.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Hands 392 Armor +9 Strength +14 Stamina +9 Intellect"] = "手 392 护甲 +9 力量 +14 耐力 +9 智力。", ["Requires Level 55"] = "需要等级 55", ["Item Level 60"] = "物品等级 60", ["Equip: Restores 4 mana per 5 sec. Equip: Increases damage done by Holy spells and effects by up to 12."] = "装备：恢复 4 法力值 per 5秒. Equip: 提高 伤害 done by Holy 法术和effects by最多12." }, "Backusarian Gauntlets"},
