    [12639] = {"要塞护手", "装备后绑定\n手 441 护甲 +18 耐力。\n需要等级 57\n装备：Immune to Disarm. Equip: 提高 你的 几率 to 招架 an attack by 1%. Equip: Improves 你的 几率 to get a 爆击 with melee和远程攻击 by 1%.", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["Hands 441 Armor +18 Stamina"] = "手 441 护甲 +18 耐力。", ["Requires Level 57"] = "需要等级 57", ["Equip: Immune to Disarm. Equip: Increases your chance to parry an attack by 1%. Equip: Improves your chance to get a critical strike with melee and ranged attacks by 1%."] = "装备：Immune to Disarm. Equip: 提高 你的 几率 to 招架 an attack by 1%. Equip: Improves 你的 几率 to get a 爆击 with melee和远程攻击 by 1%." }, "Stronghold Gauntlets"},
    [12640] = {"狮心头盔", "装备后绑定\n头部 565 护甲 +18 力量。\n需要等级 56\n物品等级 61\n装备：Improves 你的 几率 to get a 爆击 with melee和远程攻击 by 2%. Equip: Improves 你的 几率 to 命中 with melee和远程攻击 by 2%.", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["Head 565 Armor +18 Strength"] = "头部 565 护甲 +18 力量。", ["Requires Level 56"] = "需要等级 56", ["Item Level 61"] = "物品等级 61", ["Equip: Improves your chance to get a critical strike with melee and ranged attacks by 2%. Equip: Improves your chance to hit with melee and ranged attacks by 2%."] = "装备：Improves 你的 几率 to get a 爆击 with melee和远程攻击 by 2%. Equip: Improves 你的 几率 to 命中 with melee和远程攻击 by 2%." }, "Lionheart Helm"},
    [12641] = {"免伤锁甲", "装备后绑定\n胸部 624 护甲 +8 敏捷 +10 耐力 +13 to 所有抗性。\n需要等级 57\n装备：在战斗中被击中时，有 5% 的几率使你在 3 秒内免受近战伤害。该效果每 30 秒只能发生一次。", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["Chest 624 Armor +8 Agility +10 Stamina +13 to All Resistances"] = "胸部 624 护甲 +8 敏捷 +10 耐力 +13 to 所有抗性。", ["Requires Level 57"] = "需要等级 57", ["Equip: When struck in combat has a 5% chance to make you invulnerable to melee damage for 3 sec. This effect can only occur once every 30 sec."] = "装备：在战斗中被击中时，有 5% 的几率使你在 3 秒内免受近战伤害。该效果每 30 秒只能发生一次。" }, "Invulnerable Mail"},
