    [13501] = {"配方：特效法力药水", "拾取后绑定\n需要 炼金术 (295)\n使用：教你学会make a Major 法力值 Potion. nMajor 法力值 Potion。\n需要等级 49\n使用：恢复 1350 到 2250 点法力值。（2分钟冷却）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Alchemy (295)"] = "需要 炼金术 (295)", ["Use: Teaches you how to make a Major Mana Potion. nMajor Mana Potion"] = "使用：教你学会make a Major 法力值 Potion. nMajor 法力值 Potion。", ["Requires Level 49"] = "需要等级 49", ["Use: Restores 1350 to 2250 mana. (2 Min Cooldown)"] = "使用：恢复 1350 到 2250 点法力值。（2分钟冷却）" }, "Recipe: Major Mana Potion"},
    [13502] = {"手工精制束带", "拾取后绑定\n腰部 519 护甲 +11 力量 +10 敏捷 +15 耐力。\n需要等级 58\n物品等级 63", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Waist 519 Armor +11 Strength +10 Agility +15 Stamina"] = "腰部 519 护甲 +11 力量 +10 敏捷 +15 耐力。", ["Requires Level 58"] = "需要等级 58", ["Item Level 63"] = "物品等级 63" }, "Handcrafted Mastersmith Girdle"},
    [13503] = {"炼金石", "拾取后绑定\n唯一\n饰品 +8 精神。\n需要 炼金术 (300) Equip: Increases the effects that healing and mana potions have on the wearer by 33%.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Trinket +8 Spirit"] = "饰品 +8 精神。", ["Requires Alchemy (300) Equip: Increases the effects that healing and mana potions have on the wearer by 33%."] = "需要 炼金术 (300) Equip: Increases the effects that healing and mana potions have on the wearer by 33%." }, "Alchemists' Stone"},
    [13505] = {"瑞文戴尔之剑", "拾取后绑定\n双手 171 - 257 伤害 (59.4 伤害 每秒) +17 力量 +12 耐力。\n需要等级 58\n装备：提高 移动速度和life regeneration rate. Equip: Reduces 你的 几率 to be dodged or parried by 1%.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Two-Hand 171 - 257 Damage (59.4 damage per second) +17 Strength +12 Stamina"] = "双手 171 - 257 伤害 (59.4 伤害 每秒) +17 力量 +12 耐力。", ["Requires Level 58"] = "需要等级 58", ["Equip: Increases movement speed and life regeneration rate. Equip: Reduces your chance to be dodged or parried by 1%."] = "装备：提高 移动速度和life regeneration rate. Equip: Reduces 你的 几率 to be dodged or parried by 1%." }, "Runeblade of Baron Rivendare"},
    [13506] = {"化石药水", "需要等级 50\n使用：你变成石头，保护你免受所有物理攻击和法术攻击，持续 1 分钟，但在此期间你无法攻击、移动或施法。您一次只能获得一个药剂的效果。", "EpochHead 消耗品", "consumable", { ["Requires Level 50"] = "需要等级 50", ["Use: You turn to stone, protecting you from all physical attacks and spells for 1 min, but during that time you cannot attack, move or cast spells. You can only have the effect of one flask at a time."] = "使用：你变成石头，保护你免受所有物理攻击和法术攻击，持续 1 分钟，但在此期间你无法攻击、移动或施法。您一次只能获得一个药剂的效果。" }, "Flask of Petrification"},
    [13507] = {"峭壁卫兵图林·长角的报告", "任务物品\n唯一", "EpochHead 消耗品", "consumable", { ["Quest Item"] = "任务物品", ["Unique"] = "唯一" }, "Cliffwatcher Longhorn Report"},
    [13508] = {"蛛怪之眼", "拾取后绑定\n唯一\n需要等级 55\n使用：召唤一只基尔罗格之眼，并将你的视野绑定到它身上。眼睛移动很快，但非常脆弱。（1分钟冷却）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Requires Level 55"] = "需要等级 55", ["Use: Summons an Eye of Kilrogg and\nbinds your vision to it. The eye moves quickly but is very fragile. (1 Min Cooldown)"] = "使用：召唤一只基尔罗格之眼，并将你的视野绑定到它身上。眼睛移动很快，但非常脆弱。（1分钟冷却）" }, "Eye of Arachnida"},
    [13509] = {"预知之眼", "拾取后绑定\n唯一\n需要等级 55\n使用: 反击敌人的施法，阻止该魔法流派的任何法术施展，持续 10 秒。产生大量威胁。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Requires Level 55"] = "需要等级 55", ["Use: Counters the enemy's spellcast, preventing any spell from that school of magic from being cast for 10 sec. Generates a high amount of threat."] = "使用: 反击敌人的施法，阻止该魔法流派的任何法术施展，持续 10 秒。产生大量威胁。" }, "Clutch of Foresight"},
    [13510] = {"泰坦合剂", "需要等级 50\n使用: 使玩家的最大生命值增加 700 点，持续 2 小时。既可以作为战斗药剂，也可以作为守护药剂。这种效应在死亡后仍持续存在。", "EpochHead 消耗品", "consumable", { ["Requires Level 50"] = "需要等级 50", ["Use: Increases the player's maximum health by 700 for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death."] = "使用: 使玩家的最大生命值增加 700 点，持续 2 小时。既可以作为战斗药剂，也可以作为守护药剂。这种效应在死亡后仍持续存在。" }, "Flask of the Titans"},
    [13511] = {"精炼智慧合剂", "需要等级 50\n使用: 智力提高 65 点，持续 2 小时。既可以作为战斗药剂，也可以作为守护药剂。这种效应在死亡后仍持续存在。", "EpochHead 消耗品", "consumable", { ["Requires Level 50"] = "需要等级 50", ["Use: Increases Intellect by 65 for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death."] = "使用: 智力提高 65 点，持续 2 小时。既可以作为战斗药剂，也可以作为守护药剂。这种效应在死亡后仍持续存在。" }, "Flask of Distilled Wisdom"},
    [13512] = {"超级能量合剂", "需要等级 50\n使用: 使魔法法术和效果造成的伤害提高最多 70 点，持续 2 小时。既可以作为战斗药剂，也可以作为守护药剂。这种效应在死亡后仍持续存在。", "EpochHead 消耗品", "consumable", { ["Requires Level 50"] = "需要等级 50", ["Use: Increases damage done by magical spells and effects by up to 70 for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death."] = "使用: 使魔法法术和效果造成的伤害提高最多 70 点，持续 2 小时。既可以作为战斗药剂，也可以作为守护药剂。这种效应在死亡后仍持续存在。" }, "Flask of Supreme Power"},
    [13513] = {"多重抗性合剂", "需要等级 50\n使用: 使你对所有魔法流派的抵抗力提高 25 点，持续 2 小时。既可以作为战斗药剂，也可以作为守护药剂。该效果在死亡后持续存在，并与所有其他抵抗法术和物品叠加。", "EpochHead 消耗品", "consumable", { ["Requires Level 50"] = "需要等级 50", ["Use: Increases your resistance to all schools of magic by 25 for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death and stacks with all other resistance spells and items."] = "使用: 使你对所有魔法流派的抵抗力提高 25 点，持续 2 小时。既可以作为战斗药剂，也可以作为守护药剂。该效果在死亡后持续存在，并与所有其他抵抗法术和物品叠加。" }, "Flask of Chromatic Resistance"},
    [13514] = {"女妖之嚎", "拾取后绑定\n唯一\n需要等级 55\n使用: 使敌人被击中的几率降低 10%，持续 12 秒。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Requires Level 55"] = "需要等级 55", ["Use: Reduces an enemy's chance to hit by 10% for 12 sec."] = "使用: 使敌人被击中的几率降低 10%，持续 12 秒。" }, "Wail of the Banshee"},
