    [14634] = {"配方：冰霜之油", "需要 炼金术 (200)\n使用：教你学会make Frost Oil. nFrost Oil。\n需要等级 30\n使用：When applied to a 近战武器 it gives a 10% 几率 of casting Frostbolt at the opponent when it hits. Lasts 30分钟. (1秒 冷却) nRequires Khadgar's Whisker (4), Wintersbite (2), Leaded Vial。", "EpochHead 消耗品", "consumable", { ["Requires Alchemy (200)"] = "需要 炼金术 (200)", ["Use: Teaches you how to make Frost Oil. nFrost Oil"] = "使用：教你学会make Frost Oil. nFrost Oil。", ["Requires Level 30"] = "需要等级 30", ["Use: When applied to a melee weapon it gives a 10% chance of casting Frostbolt at the opponent when it hits. Lasts 30 minutes. (1 Sec Cooldown) nRequires Khadgar's Whisker (4), Wintersbite (2), Leaded Vial"] = "使用：When applied to a 近战武器 it gives a 10% 几率 of casting Frostbolt at the opponent when it hits. Lasts 30分钟. (1秒 冷却) nRequires Khadgar's Whisker (4), Wintersbite (2), Leaded Vial。" }, "Recipe: Frost Oil"},
    [14635] = {"图样：宝石皮带", "普通\n需要 制皮 (185)\n使用：教你学会craft a Gem-studded Leather 腰带. nGem-studded Leather 腰带。\n精良\n装备后绑定\n腰部 65 护甲 +12 耐力 +6 精神。\n需要等级 32\n物品等级 37\n使用：Heal yourself for 225 to 375. (1小时 冷却) nRequires Cured Heavy Hide (4), Iridescent Pearl (2), Jade (2), Citrine, Fine Thread。", "EpochHead 消耗品", "consumable", { ["Common"] = "普通", ["Requires Leatherworking (185)"] = "需要 制皮 (185)", ["Use: Teaches you how to craft a Gem-studded Leather Belt. nGem-studded Leather Belt"] = "使用：教你学会craft a Gem-studded Leather 腰带. nGem-studded Leather 腰带。", ["Rare"] = "精良", ["Binds when equipped"] = "装备后绑定", ["Waist 65 Armor +12 Stamina +6 Spirit"] = "腰部 65 护甲 +12 耐力 +6 精神。", ["Requires Level 32"] = "需要等级 32", ["Item Level 37"] = "物品等级 37", ["Use: Heal yourself for 225 to 375. (1 Hr Cooldown) nRequires Cured Heavy Hide (4), Iridescent Pearl (2), Jade (2), Citrine, Fine Thread"] = "使用：Heal yourself for 225 to 375. (1小时 冷却) nRequires Cured Heavy Hide (4), Iridescent Pearl (2), Jade (2), Citrine, Fine Thread。" }, "Pattern: Gem-studded Leather Belt"},
