    [16023] = {"高级活动假人", "需要 工程学 (275)\n使用: 将一个目标假人扔在地上，吸引附近的怪物攻击它。持续15秒或直到被杀死。", "EpochHead 消耗品", "consumable", { ["Requires Engineering (275)"] = "需要 工程学 (275)", ["Use: Drops a target dummy on the ground that attracts nearby monsters to attack it. Lasts for 15 seconds or until killed."] = "使用: 将一个目标假人扔在地上，吸引附近的怪物攻击它。持续15秒或直到被杀死。" }, "Masterwork Target Dummy"},
    [16039] = {"塔基尔萨歌唱之剑", "装备后绑定\n双手 129 - 194 伤害 +1 - 20 Arcane 伤害 (52.1 伤害 每秒)。\n需要等级 52\n物品等级 57", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["Two-Hand 129 - 194 Damage +1 - 20 Arcane Damage (52.1 damage per second)"] = "双手 129 - 194 伤害 +1 - 20 Arcane 伤害 (52.1 伤害 每秒)。", ["Requires Level 52"] = "需要等级 52", ["Item Level 57"] = "物品等级 57" }, "Ta'Kierthan Songblade"},
    [16040] = {"奥术炸弹", "需要 工程学 (300)\n使用: 从爆炸半径内吸取 675 到 1125 点法力，并对目标造成伤害，造成所吸取法力的 50%。还能使爆炸中的目标沉默 5 秒。", "EpochHead 消耗品", "consumable", { ["Requires Engineering (300)"] = "需要 工程学 (300)", ["Use: Drains 675 to 1125 mana from those in the blast radius and does 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec."] = "使用: 从爆炸半径内吸取 675 到 1125 点法力，并对目标造成伤害，造成所吸取法力的 50%。还能使爆炸中的目标沉默 5 秒。" }, "Arcane Bomb"},
