    [18403] = {"屠龙者的徽记", "拾取后绑定\n手指 +10 耐力 +7 智力 +10 火焰抗性 物品 等级 67。\n装备：Improves 你的 几率 to get a 爆击 with 法术 by 1%. Equip: 提高 伤害和治疗效果 done by magical 法术和effects by最多12.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Finger +10 Stamina +7 Intellect +10 Fire Resistance Item Level 67"] = "手指 +10 耐力 +7 智力 +10 火焰抗性 物品 等级 67。", ["Equip: Improves your chance to get a critical strike with spells by 1%. Equip: Increases damage and healing done by magical spells and effects by up to 12."] = "装备：Improves 你的 几率 to get a 爆击 with 法术 by 1%. Equip: 提高 伤害和治疗效果 done by magical 法术和effects by最多12." }, "Dragonslayer's Signet"},
    [18404] = {"奥妮克希亚龙牙坠饰", "拾取后绑定\n颈部 +11 敏捷 +9 耐力 +10 火焰抗性 物品 等级 67。\n装备：Improves 你的 几率 to 命中 with melee和远程攻击 by 1%. Equip: Improves 你的 几率 to get a 爆击 with melee和远程攻击 by 1%.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Neck +11 Agility +9 Stamina +10 Fire Resistance Item Level 67"] = "颈部 +11 敏捷 +9 耐力 +10 火焰抗性 物品 等级 67。", ["Equip: Improves your chance to hit with melee and ranged attacks by 1%. Equip: Improves your chance to get a critical strike with melee and ranged attacks by 1%."] = "装备：Improves 你的 几率 to 命中 with melee和远程攻击 by 1%. Equip: Improves 你的 几率 to get a 爆击 with melee和远程攻击 by 1%." }, "Onyxia Tooth Pendant"},
    [18406] = {"奥妮克希亚龙血护符", "拾取后绑定\n饰品 +15 火焰抗性。\n装备：提高 你的 几率 to 招架 an attack by 1%. Equip: Increased 防御 +6. Equip: 恢复 7 生命值 per 5秒.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Trinket +15 Fire Resistance"] = "饰品 +15 火焰抗性。", ["Equip: Increases your chance to parry an attack by 1%. Equip: Increased Defense +6. Equip: Restores 7 health per 5 sec."] = "装备：提高 你的 几率 to 招架 an attack by 1%. Equip: Increased 防御 +6. Equip: 恢复 7 生命值 per 5秒." }, "Onyxia Blood Talisman"},
