    [18517] = {"图样：多彩披风", "需要 制皮 (300)\n需要 Dragonscale 制皮\n需要 瑟银Brotherhood-Exalted\n使用：教你学会craft a Chromatic 披风. nChromatic 披风。\n装备后绑定\n背部 48 护甲 +10 耐力 +8 火焰抗性 +8 暗影抗性。\n需要等级 58\n物品等级 63\n装备：Improves 你的 几率 to get a 爆击 with 法术 by 1%. Equip: 提高 伤害和治疗效果 done by magical 法术和effects by最多8. nRequires Rugged Leather (30), Brilliant Chromatic Scale (12), Black Dragonscale (30), Red Dragonscale (30), Cured Rugged Hide (5), Rune Thread (8)。", "EpochHead 消耗品", "consumable", { ["Requires Leatherworking (300)"] = "需要 制皮 (300)", ["Requires Dragonscale Leatherworking"] = "需要 Dragonscale 制皮", ["Requires Thorium Brotherhood - Exalted Use: Teaches you how to craft a Chromatic Cloak. nChromatic Cloak"] = "需要 瑟银Brotherhood-Exalted\n使用：教你学会craft a Chromatic 披风. nChromatic 披风。", ["Binds when equipped"] = "装备后绑定", ["Back 48 Armor +10 Stamina +8 Fire Resistance +8 Shadow Resistance"] = "背部 48 护甲 +10 耐力 +8 火焰抗性 +8 暗影抗性。", ["Requires Level 58"] = "需要等级 58", ["Item Level 63"] = "物品等级 63", ["Equip: Improves your chance to get a critical strike with spells by 1%. Equip: Increases damage and healing done by magical spells and effects by up to 8. nRequires Rugged Leather (30), Brilliant Chromatic Scale (12), Black Dragonscale (30), Red Dragonscale (30), Cured Rugged Hide (5), Rune Thread (8)"] = "装备：Improves 你的 几率 to get a 爆击 with 法术 by 1%. Equip: 提高 伤害和治疗效果 done by magical 法术和effects by最多8. nRequires Rugged Leather (30), Brilliant Chromatic Scale (12), Black Dragonscale (30), Red Dragonscale (30), Cured Rugged Hide (5), Rune Thread (8)。" }, "Pattern: Chromatic Cloak"},
    [18518] = {"图样：野性之皮", "需要 制皮 (300) Already known\n需要 Tribal 制皮\n需要 Valor的Expedition-Exalted\n使用：教你学会craft a Hide of the Wild. nHide of the Wild。\n装备后绑定\n背部 48 护甲 +12 耐力 +10 智力。\n需要等级 57\n物品等级 62\n装备：提高 治疗效果 done by最多42和伤害 done by最多14 for all magical 法术和effects. nRequires Rugged Leather (30), Living Essence (12), Essence of Water (10), Larval Acid (8), Cured Rugged Hide (3), Rune Thread (8)。", "EpochHead 消耗品", "consumable", { ["Requires Leatherworking (300) Already known"] = "需要 制皮 (300) Already known", ["Requires Tribal Leatherworking"] = "需要 Tribal 制皮", ["Requires Valor's Expedition - Exalted Use: Teaches you how to craft a Hide of the Wild. nHide of the Wild"] = "需要 Valor的Expedition-Exalted\n使用：教你学会craft a Hide of the Wild. nHide of the Wild。", ["Binds when equipped"] = "装备后绑定", ["Back 48 Armor +12 Stamina +10 Intellect"] = "背部 48 护甲 +12 耐力 +10 智力。", ["Requires Level 57"] = "需要等级 57", ["Item Level 62"] = "物品等级 62", ["Equip: Increases healing done by up to 42 and damage done by up to 14 for all magical spells and effects. nRequires Rugged Leather (30), Living Essence (12), Essence of Water (10), Larval Acid (8), Cured Rugged Hide (3), Rune Thread (8)"] = "装备：提高 治疗效果 done by最多42和伤害 done by最多14 for all magical 法术和effects. nRequires Rugged Leather (30), Living Essence (12), Essence of Water (10), Larval Acid (8), Cured Rugged Hide (3), Rune Thread (8)。" }, "Pattern: Hide of the Wild"},
    [18519] = {"图样：移形披风", "需要 制皮 (300)\n需要 Elemental 制皮\n需要 Valor的Expedition-Exalted\n使用：教你学会craft a Shifting 披风. nShifting 披风。\n装备后绑定\n背部 48 护甲 +17 敏捷 +12 耐力。\n需要等级 57\n物品等级 62\n装备：提高 你的 几率 to 躲闪 an attack by 1%. nRequires Rugged Leather (30), Essence of Air (12), Skin of Shadow (4), Guardian Stone (8), Cured Rugged Hide (4), Rune Thread (8)。", "EpochHead 消耗品", "consumable", { ["Requires Leatherworking (300)"] = "需要 制皮 (300)", ["Requires Elemental Leatherworking"] = "需要 Elemental 制皮", ["Requires Valor's Expedition - Exalted Use: Teaches you how to craft a Shifting Cloak. nShifting Cloak"] = "需要 Valor的Expedition-Exalted\n使用：教你学会craft a Shifting 披风. nShifting 披风。", ["Binds when equipped"] = "装备后绑定", ["Back 48 Armor +17 Agility +12 Stamina"] = "背部 48 护甲 +17 敏捷 +12 耐力。", ["Requires Level 57"] = "需要等级 57", ["Item Level 62"] = "物品等级 62", ["Equip: Increases your chance to dodge an attack by 1%. nRequires Rugged Leather (30), Essence of Air (12), Skin of Shadow (4), Guardian Stone (8), Cured Rugged Hide (4), Rune Thread (8)"] = "装备：提高 你的 几率 to 躲闪 an attack by 1%. nRequires Rugged Leather (30), Essence of Air (12), Skin of Shadow (4), Guardian Stone (8), Cured Rugged Hide (4), Rune Thread (8)。" }, "Pattern: Shifting Cloak"},
