    [19287] = {"暗月卡片：英雄", "史诗\n拾取后绑定\n唯一\n饰品\n需要等级 60\n物品等级 66\n装备：Sometimes heals bearer of 120 to 180 伤害 when damaging an enemy in melee.", "EpochHead 消耗品", "consumable", { ["Epic"] = "史诗", ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Trinket"] = "饰品", ["Requires Level 60"] = "需要等级 60", ["Item Level 66"] = "物品等级 66", ["Equip: Sometimes heals bearer of 120 to 180 damage when damaging an enemy in melee."] = "装备：Sometimes heals bearer of 120 to 180 伤害 when damaging an enemy in melee." }, "Darkmoon Card: Heroism"},
    [19289] = {"暗月卡片：漩涡", "史诗\n拾取后绑定\n唯一\n饰品\n需要等级 60\n物品等级 66\n装备：有几率用闪电攻击你的近战目标，造成 200 到 300 点自然伤害。", "EpochHead 消耗品", "consumable", { ["Epic"] = "史诗", ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Trinket"] = "饰品", ["Requires Level 60"] = "需要等级 60", ["Item Level 66"] = "物品等级 66", ["Equip: Chance to strike your melee target with lightning for 200 to 300 Nature damage."] = "装备：有几率用闪电攻击你的近战目标，造成 200 到 300 点自然伤害。" }, "Darkmoon Card: Maelstrom"},
    [19291] = {"暗月储物箱", "唯一\n14 Slot Bag", "EpochHead 消耗品", "consumable", { ["Unique"] = "唯一" }, "Darkmoon Storage Box"},
    [19298] = {"初级暗月奖品", "需要等级 15\nGuaranteed to contain an 物品 of value!", "EpochHead 消耗品", "consumable", { ["Requires Level 15"] = "需要等级 15", ["\"Guaranteed to contain an item of value!\""] = "Guaranteed to contain an 物品 of value!" }, "Minor Darkmoon Prize"},
    [19301] = {"奥特兰克魔法点心", "拾取后绑定\n需要等级 51\n使用：在 30秒 内恢复 4410 点生命值和 4410 点法力值。进食时必须保持坐姿。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Level 51"] = "需要等级 51", ["Use: Restores 4410 health and 4410 mana over 30 sec. Must remain seated while eating."] = "使用：在 30秒 内恢复 4410 点生命值和 4410 点法力值。进食时必须保持坐姿。" }, "Alterac Manna Biscuit"},
    [19304] = {"辣牛肉干", "需要等级 5\n使用：在 21秒 内恢复 243 点生命值。进食时必须保持坐姿。", "EpochHead 消耗品", "consumable", { ["Requires Level 5"] = "需要等级 5", ["Use: Restores 243 health over 21 sec. Must remain seated while eating."] = "使用：在 21秒 内恢复 243 点生命值。进食时必须保持坐姿。" }, "Spiced Beef Jerky"},
    [19311] = {"火焰魔法宝典", "拾取后绑定\n唯一\n副手物品\n需要等级 60\n物品等级 65\n装备：火焰法术和效果造成的伤害最多提高 40 点。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Held In Off-hand"] = "副手物品", ["Requires Level 60"] = "需要等级 60", ["Item Level 65"] = "物品等级 65", ["Equip: Increases damage done by Fire spells and effects by up to 40."] = "装备：火焰法术和效果造成的伤害最多提高 40 点。" }, "Tome of Fiery Arcana"},
    [19326] = {"图样：木喉之力", "拾取后绑定\n需要 制皮 (290)\n需要 Timbermaw Hold - Honored\n使用：教你学会craft the Might of the Timbermaw. Retrieving 物品 information nRequires Rugged Leather (30), Powerful Mojo (2), Living Essence (4), Cured Rugged Hide (2), Rune Thread (2)。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Leatherworking (290)"] = "需要 制皮 (290)", ["Requires Timbermaw Hold - Honored Use: Teaches you how to craft the Might of the Timbermaw. Retrieving item information nRequires Rugged Leather (30), Powerful Mojo (2), Living Essence (4), Cured Rugged Hide (2), Rune Thread (2)"] = "需要 Timbermaw Hold - Honored\n使用：教你学会craft the Might of the Timbermaw. Retrieving 物品 information nRequires Rugged Leather (30), Powerful Mojo (2), Living Essence (4), Cured Rugged Hide (2), Rune Thread (2)。" }, "Pattern: Might of the Timbermaw"},
    [19327] = {"图样：木喉作战手套", "拾取后绑定\n需要 制皮 (300)\n需要 Timbermaw Hold - Revered\n使用：教你学会craft Timbermaw Brawlers. Retrieving 物品 information nRequires Enchanted Leather (8), Powerful Mojo (6), Living Essence (6), Cured Rugged Hide (2), Ironweb Spider Silk (2)。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Leatherworking (300)"] = "需要 制皮 (300)", ["Requires Timbermaw Hold - Revered Use: Teaches you how to craft Timbermaw Brawlers. Retrieving item information nRequires Enchanted Leather (8), Powerful Mojo (6), Living Essence (6), Cured Rugged Hide (2), Ironweb Spider Silk (2)"] = "需要 Timbermaw Hold - Revered\n使用：教你学会craft Timbermaw Brawlers. Retrieving 物品 information nRequires Enchanted Leather (8), Powerful Mojo (6), Living Essence (6), Cured Rugged Hide (2), Ironweb Spider Silk (2)。" }, "Pattern: Timbermaw Brawlers"},
    [19328] = {"图样：黎明皮靴", "拾取后绑定\n需要 制皮 (290)\n需要 Argent Dawn - Honored\n使用：教你学会craft Dawn Treaders. nDawn Treaders。\n装备后绑定\n脚 114 护甲 +13 力量 +20 耐力。\n需要等级 53\n物品等级 58\n装备：提高 你的 几率 to 躲闪 an attack by 1%. nRequires Rugged Leather (30), Guardian Stone (2), Essence of Water (4), Cured Rugged Hide (2), Rune Thread (2)。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Leatherworking (290)"] = "需要 制皮 (290)", ["Requires Argent Dawn - Honored Use: Teaches you how to craft Dawn Treaders. nDawn Treaders"] = "需要 Argent Dawn - Honored\n使用：教你学会craft Dawn Treaders. nDawn Treaders。", ["Binds when equipped"] = "装备后绑定", ["Feet 114 Armor +13 Strength +20 Stamina"] = "脚 114 护甲 +13 力量 +20 耐力。", ["Requires Level 53"] = "需要等级 53", ["Item Level 58"] = "物品等级 58", ["Equip: Increases your chance to dodge an attack by 1%. nRequires Rugged Leather (30), Guardian Stone (2), Essence of Water (4), Cured Rugged Hide (2), Rune Thread (2)"] = "装备：提高 你的 几率 to 躲闪 an attack by 1%. nRequires Rugged Leather (30), Guardian Stone (2), Essence of Water (4), Cured Rugged Hide (2), Rune Thread (2)。" }, "Pattern: Dawn Treaders"},
    [19329] = {"图样：金色黎明衬肩", "拾取后绑定\n需要 制皮 (300)\n需要 Argent Dawn - Revered\n使用：教你学会craft a Golden Mantle of the Dawn. nGolden Mantle of the Dawn。\n装备后绑定\n肩部 194 护甲 +14 敏捷 +12 耐力。\n需要等级 59\n物品等级 64\n装备：提高 你的 几率 to 躲闪 an attack by 1%. Equip: Improves 你的 几率 to 命中 with melee和远程攻击 by 1%. nRequires Enchanted Leather (8), Living Essence (4), Guardian Stone (4), Cured Rugged Hide (2), Rune Thread (2)。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Leatherworking (300)"] = "需要 制皮 (300)", ["Requires Argent Dawn - Revered Use: Teaches you how to craft a Golden Mantle of the Dawn. nGolden Mantle of the Dawn"] = "需要 Argent Dawn - Revered\n使用：教你学会craft a Golden Mantle of the Dawn. nGolden Mantle of the Dawn。", ["Binds when equipped"] = "装备后绑定", ["Shoulder 194 Armor +14 Agility +12 Stamina"] = "肩部 194 护甲 +14 敏捷 +12 耐力。", ["Requires Level 59"] = "需要等级 59", ["Item Level 64"] = "物品等级 64", ["Equip: Increases your chance to dodge an attack by 1%. Equip: Improves your chance to hit with melee and ranged attacks by 1%. nRequires Enchanted Leather (8), Living Essence (4), Guardian Stone (4), Cured Rugged Hide (2), Rune Thread (2)"] = "装备：提高 你的 几率 to 躲闪 an attack by 1%. Equip: Improves 你的 几率 to 命中 with melee和远程攻击 by 1%. nRequires Enchanted Leather (8), Living Essence (4), Guardian Stone (4), Cured Rugged Hide (2), Rune Thread (2)。" }, "Pattern: Golden Mantle of the Dawn"},
    [19330] = {"图样：熔岩腰带", "拾取后绑定\n需要 Leatherworking (300) Already known\n使用：教你学会craft a Lava 腰带. nLava 腰带。\n装备后绑定\n腰部 273 护甲 +15 耐力 +28 火焰抗性。\n需要等级 60\n物品 等级 66 Lava Leather (0/8) Lava 腰带 Lava Bracers Lava 靴子 Lava Gauntlets Lava Helm Lava Chestguard Lava Leggings Fireguard Shoulders (2) Set: +10 火焰抗性. (4) Set: +36 攻击强度 when fighting Elementals. (6) Set: Improves 你的 几率 to 命中 with melee和远程攻击 by 1%. (8) Set: While you are in an area touched by the Firelord, 你的 攻击强度 is increased by 75. n。\n需要 LavaCore(5),Cured硬甲Hide(4),IronwebSpider丝质(4)", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Leatherworking (300) Already known Use: Teaches you how to craft a Lava Belt. nLava Belt"] = "需要 Leatherworking (300) Already known\n使用：教你学会craft a Lava 腰带. nLava 腰带。", ["Binds when equipped"] = "装备后绑定", ["Waist 273 Armor +15 Stamina +28 Fire Resistance"] = "腰部 273 护甲 +15 耐力 +28 火焰抗性。", ["Requires Level 60"] = "需要等级 60", ["Item Level 66 Lava Leather (0/8) Lava Belt Lava Bracers Lava Boots Lava Gauntlets Lava Helm Lava Chestguard Lava Leggings Fireguard Shoulders (2) Set: +10 Fire Resistance. (4) Set: +36 Attack Power when fighting Elementals. (6) Set: Improves your chance to hit with melee and ranged attacks by 1%. (8) Set: While you are in an area touched by the Firelord, your attack power is increased by 75. n"] = "物品 等级 66 Lava Leather (0/8) Lava 腰带 Lava Bracers Lava 靴子 Lava Gauntlets Lava Helm Lava Chestguard Lava Leggings Fireguard Shoulders (2) Set: +10 火焰抗性. (4) Set: +36 攻击强度 when fighting Elementals. (6) Set: Improves 你的 几率 to 命中 with melee和远程攻击 by 1%. (8) Set: While you are in an area touched by the Firelord, 你的 攻击强度 is increased by 75. n。", ["Requires Lava Core (5), Cured Rugged Hide (4), Ironweb Spider Silk (4)"] = "需要 LavaCore(5),Cured硬甲Hide(4),IronwebSpider丝质(4)" }, "Pattern: Lava Belt"},
    [19331] = {"图样：多彩护手", "拾取后绑定\n需要 制皮 (300) Already known\n需要 Dragonscale Leatherworking\n使用：教你学会craft Chromatic Gauntlets. nChromatic Gauntlets。\n装备后绑定\n手 263 护甲 +5 to 所有抗性。\n需要等级 60\n物品等级 66\n装备：提高 攻击强度 by 32. Equip: Improves 你的 几率 to get a 爆击 with melee和远程攻击 by 1%. Equip: Improves 你的 几率 to get a 爆击 with 法术 by 1%. nRequires Fiery Core (5), Lava Core (2), Core Leather (4), Brilliant Chromatic Scale (4), Cured Rugged Hide (4), Ironweb Spider Silk (4)。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Leatherworking (300) Already known"] = "需要 制皮 (300) Already known", ["Requires Dragonscale Leatherworking Use: Teaches you how to craft Chromatic Gauntlets. nChromatic Gauntlets"] = "需要 Dragonscale Leatherworking\n使用：教你学会craft Chromatic Gauntlets. nChromatic Gauntlets。", ["Binds when equipped"] = "装备后绑定", ["Hands 263 Armor +5 to All Resistances"] = "手 263 护甲 +5 to 所有抗性。", ["Requires Level 60"] = "需要等级 60", ["Item Level 66"] = "物品等级 66", ["Equip: Increases attack power by 32. Equip: Improves your chance to get a critical strike with melee and ranged attacks by 1%. Equip: Improves your chance to get a critical strike with spells by 1%. nRequires Fiery Core (5), Lava Core (2), Core Leather (4), Brilliant Chromatic Scale (4), Cured Rugged Hide (4), Ironweb Spider Silk (4)"] = "装备：提高 攻击强度 by 32. Equip: Improves 你的 几率 to get a 爆击 with melee和远程攻击 by 1%. Equip: Improves 你的 几率 to get a 爆击 with 法术 by 1%. nRequires Fiery Core (5), Lava Core (2), Core Leather (4), Brilliant Chromatic Scale (4), Cured Rugged Hide (4), Ironweb Spider Silk (4)。" }, "Pattern: Chromatic Gauntlets"},
    [19332] = {"图样：熔火犬皮腰带", "拾取后绑定\n需要 制皮 (300)\n需要 Tribal Leatherworking\n使用：教你学会craft a Corehound 腰带. nCorehound 腰带。\n装备后绑定\n腰部 112 护甲 +13 智力 +15 火焰抗性。\n需要等级 60\n物品等级 66\n装备：提高 治疗效果 done by最多49和伤害 done by最多16 for all magical 法术和effects. nRequires Fiery Core (8), Core Leather (12), Enchanted Leather (10), Cured Rugged Hide (4), Ironweb Spider Silk (4)。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Leatherworking (300)"] = "需要 制皮 (300)", ["Requires Tribal Leatherworking Use: Teaches you how to craft a Corehound Belt. nCorehound Belt"] = "需要 Tribal Leatherworking\n使用：教你学会craft a Corehound 腰带. nCorehound 腰带。", ["Binds when equipped"] = "装备后绑定", ["Waist 112 Armor +13 Intellect +15 Fire Resistance"] = "腰部 112 护甲 +13 智力 +15 火焰抗性。", ["Requires Level 60"] = "需要等级 60", ["Item Level 66"] = "物品等级 66", ["Equip: Increases healing done by up to 49 and damage done by up to 16 for all magical spells and effects. nRequires Fiery Core (8), Core Leather (12), Enchanted Leather (10), Cured Rugged Hide (4), Ironweb Spider Silk (4)"] = "装备：提高 治疗效果 done by最多49和伤害 done by最多16 for all magical 法术和effects. nRequires Fiery Core (8), Core Leather (12), Enchanted Leather (10), Cured Rugged Hide (4), Ironweb Spider Silk (4)。" }, "Pattern: Corehound Belt"},
