    [19990] = {"祝福珠串", "拾取后绑定\n饰品 物品 等级 52。\n使用: 使法术和效果的治疗效果提高最多 190 点，持续 20 秒。 （2 分钟冷却时间）\nA friend in need is a friend without beads.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Trinket Item Level 52"] = "饰品 物品 等级 52。", ["Use: Increases healing done by spells and effects by up to 190 for 20 sec. (2 Min Cooldown)"] = "使用: 使法术和效果的治疗效果提高最多 190 点，持续 20 秒。 （2 分钟冷却时间）", ["\"A friend in need is a friend without beads.\""] = "A friend in need is a friend without beads." }, "Blessed Prayer Beads"},
    [19991] = {"魔暴龙眼", "拾取后绑定\n饰品 物品 等级 52。\n使用: 使你的攻击力提高 150 点，命中几率提高 2%。效果持续20秒。 （2 分钟冷却时间）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Trinket Item Level 52"] = "饰品 物品 等级 52。", ["Use: Increases your attack power by 150 and your chance to hit by 2%. Effect lasts for 20 sec. (2 Min Cooldown)"] = "使用: 使你的攻击力提高 150 点，命中几率提高 2%。效果持续20秒。 （2 分钟冷却时间）" }, "Devilsaur Eye"},
    [19992] = {"魔暴龙牙", "拾取后绑定\n饰品 物品 等级 52。\n使用: 如果你的宠物的下一次攻击能够造成暴击，那么它的下一次攻击就一定会造成暴击。 （2 分钟冷却时间）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Trinket Item Level 52"] = "饰品 物品 等级 52。", ["Use: Your pet's next attack is guaranteed to critically strike if that attack is capable of striking critically. (2 Min Cooldown)"] = "使用: 如果你的宠物的下一次攻击能够造成暴击，那么它的下一次攻击就一定会造成暴击。 （2 分钟冷却时间）" }, "Devilsaur Tooth"},
    [20003] = {"魔暴龙爪", "拾取后绑定\n主手 57 - 108 伤害 (34.4 伤害 每秒) +5 敏捷。\n需要等级 50\n物品等级 52\n装备：Improves 你的 几率 to 命中 with melee和远程攻击 by 1%. Devilsaur Claws (0/2) Devilsaur's Right Claws Devilsaur's Left Claws (2) Set: 你的 attacks have a 10% 几率 to increase 你的 攻击速度 by 15% for 15秒.\nThe claws hum with primal 能量.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Main Hand 57 - 108 Damage (34.4 damage per second) +5 Agility"] = "主手 57 - 108 伤害 (34.4 伤害 每秒) +5 敏捷。", ["Requires Level 50"] = "需要等级 50", ["Item Level 52"] = "物品等级 52", ["Equip: Improves your chance to hit with melee and ranged attacks by 1%. Devilsaur Claws (0/2) Devilsaur's Right Claws Devilsaur's Left Claws (2) Set: Your attacks have a 10% chance to increase your attack speed by 15% for 15 sec."] = "装备：Improves 你的 几率 to 命中 with melee和远程攻击 by 1%. Devilsaur Claws (0/2) Devilsaur's Right Claws Devilsaur's Left Claws (2) Set: 你的 attacks have a 10% 几率 to increase 你的 攻击速度 by 15% for 15秒.", ["\"The claws hum with primal energy.\""] = "The claws hum with primal 能量." }, "Devilsaur's Right Claws"},
    [20005] = {"魔暴龙爪", "拾取后绑定\n副手 43 - 81 伤害 (34.4 伤害 每秒) +5 敏捷。\n需要等级 50\n物品等级 52\n装备：Reduces 你的 几率 to be dodged or parried by 1%. Devilsaur Claws (0/2) Devilsaur's Right Claws Devilsaur's Left Claws (2) Set: 你的 attacks have a 10% 几率 to increase 你的 攻击速度 by 15% for 15秒.\nThe claws hum with primal 能量.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Off Hand 43 - 81 Damage (34.4 damage per second) +5 Agility"] = "副手 43 - 81 伤害 (34.4 伤害 每秒) +5 敏捷。", ["Requires Level 50"] = "需要等级 50", ["Item Level 52"] = "物品等级 52", ["Equip: Reduces your chance to be dodged or parried by 1%. Devilsaur Claws (0/2) Devilsaur's Right Claws Devilsaur's Left Claws (2) Set: Your attacks have a 10% chance to increase your attack speed by 15% for 15 sec."] = "装备：Reduces 你的 几率 to be dodged or parried by 1%. Devilsaur Claws (0/2) Devilsaur's Right Claws Devilsaur's Left Claws (2) Set: 你的 attacks have a 10% 几率 to increase 你的 攻击速度 by 15% for 15秒.", ["\"The claws hum with primal energy.\""] = "The claws hum with primal 能量." }, "Devilsaur's Left Claws"},
    [20006] = {"希望之环", "拾取后绑定\n手指 +6 暗影抗性 物品 等级 52。\n装备：使你的神圣法术的暴击率提高1%。\nForged from pure light.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Finger +6 Shadow Resistance Item Level 52"] = "手指 +6 暗影抗性 物品 等级 52。", ["Equip: Increases the critical effect chance of your Holy spells by 1%."] = "装备：使你的神圣法术的暴击率提高1%。", ["\"Forged from pure light.\""] = "Forged from pure light." }, "Circle of Hope"},
    [20007] = {"魔血药剂", "需要等级 40\n使用: 每 5 秒恢复 12 点法力，持续 1 小时。守护灵丹。", "EpochHead 消耗品", "consumable", { ["Requires Level 40"] = "需要等级 40", ["Use: Regenerate 12 mana per 5 sec for 1 hour. Guardian Elixir."] = "使用: 每 5 秒恢复 12 点法力，持续 1 小时。守护灵丹。" }, "Mageblood Elixir"},
    [20008] = {"活力行动药水", "需要等级 47\n使用：使你免疫昏迷和移动限制效果，持续 5秒。同时移除已有的昏迷和移动限制效果。（2分钟冷却）", "EpochHead 消耗品", "consumable", { ["Requires Level 47"] = "需要等级 47", ["Use: Makes you immune to Stun and Movement Impairing effects for the next 5 sec. Also removes existing Stun and Movement Impairing effects. (2 Min Cooldown)"] = "使用：使你免疫昏迷和移动限制效果，持续 5秒。同时移除已有的昏迷和移动限制效果。（2分钟冷却）" }, "Living Action Potion"},
    [20011] = {"配方：魔血药剂", "拾取后绑定\n需要 炼金术 (275)\n需要 Zandalar Tribe - Revered\n使用：教你学会make a Mageblood Elixir. nMageblood Elixir。\n需要等级 40\n使用：Regenerate 12 法力值 per 5秒 for 1小时. 守护药剂. nRequires Dreamfoil, Plaguebloom (2), Crystal Vial。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Alchemy (275)"] = "需要 炼金术 (275)", ["Requires Zandalar Tribe - Revered Use: Teaches you how to make a Mageblood Elixir. nMageblood Elixir"] = "需要 Zandalar Tribe - Revered\n使用：教你学会make a Mageblood Elixir. nMageblood Elixir。", ["Requires Level 40"] = "需要等级 40", ["Use: Regenerate 12 mana per 5 sec for 1 hour. Guardian Elixir. nRequires Dreamfoil, Plaguebloom (2), Crystal Vial"] = "使用：Regenerate 12 法力值 per 5秒 for 1小时. 守护药剂. nRequires Dreamfoil, Plaguebloom (2), Crystal Vial。" }, "Recipe: Mageblood Elixir"},
