    [20035] = {"冰川之矛", "拾取后绑定\n单手 31 - 59 伤害 (34.6 伤害 每秒) +4 智力 物品 等级 52。\n装备：你的冰箭法术在施展时有 6% 的几率恢复 50 点法力。\nDiabolical runes adorn the blade.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["One-Hand 31 - 59 Damage (34.6 damage per second) +4 Intellect Item Level 52"] = "单手 31 - 59 伤害 (34.6 伤害 每秒) +4 智力 物品 等级 52。", ["Equip: Your Frostbolt spells have a 6% chance to restore 50 mana when cast."] = "装备：你的冰箭法术在施展时有 6% 的几率恢复 50 点法力。", ["\"Diabolical runes adorn the blade.\""] = "Diabolical runes adorn the blade." }, "Glacial Spike"},
    [20036] = {"火焰宝石", "拾取后绑定\n饰品 物品 等级 52。\n使用: 恢复 1 到 500 点法力，并使你的下一个火焰法术的伤害提高最多 100 点。效果持续 1 分钟。 （3 分钟冷却时间）\nUnpredictability leads to both victory和death.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Trinket Item Level 52"] = "饰品 物品 等级 52。", ["Use: Restores 1 to 500 mana and increases the damage of your next Fire spell by up to 100. Effect lasts for 1 min. (3 Min Cooldown)"] = "使用: 恢复 1 到 500 点法力，并使你的下一个火焰法术的伤害提高最多 100 点。效果持续 1 分钟。 （3 分钟冷却时间）", ["\"Unpredictability leads to both victory and death.\""] = "Unpredictability leads to both victory和death." }, "Fire Ruby"},
    [20037] = {"奥术水晶坠饰", "拾取后绑定\n颈部 +6 智力 物品 等级 52。\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 16 点。\nArcane crystals are best utilized for the purposes of a mage.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Neck +6 Intellect Item Level 52"] = "颈部 +6 智力 物品 等级 52。", ["Equip: Increases damage and healing done by magical spells and effects by up to 16."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 16 点。", ["\"Arcane crystals are best utilized for the purposes of a mage.\""] = "Arcane crystals are best utilized for the purposes of a mage." }, "Arcane Crystal Pendant"},
