    [22046] = {"瓦塔拉克饰品的右半边", "任务物品\n唯一\n使用: 将瓦尔塔拉克勋爵护身符的左侧、右侧和顶部碎片重新组合成一个整体。\nThis section of the amulet vibrates with a palpable fervor to be rejoined with its sibling pieces.", "EpochHead 消耗品", "consumable", { ["Quest Item"] = "任务物品", ["Unique"] = "唯一", ["Use: Recombines the left, right and top pieces of Lord Valthalak's Amulet into one whole."] = "使用: 将瓦尔塔拉克勋爵护身符的左侧、右侧和顶部碎片重新组合成一个整体。", ["\"This section of the amulet vibrates with a palpable fervor to be rejoined with its sibling pieces.\""] = "This section of the amulet vibrates with a palpable fervor to be rejoined with its sibling pieces." }, "Right Piece of Lord Valthalak's Amulet"},
    [22047] = {"瓦塔拉克饰品的上半边", "任务物品\n唯一\n使用: 将瓦尔塔拉克勋爵护身符的左侧、右侧和顶部碎片重新组合成一个整体。\nThis object feels wrong to the touch, as if an evil within is trying to escape.", "EpochHead 消耗品", "consumable", { ["Quest Item"] = "任务物品", ["Unique"] = "唯一", ["Use: Recombines the left, right and top pieces of Lord Valthalak's Amulet into one whole."] = "使用: 将瓦尔塔拉克勋爵护身符的左侧、右侧和顶部碎片重新组合成一个整体。", ["\"This object feels wrong to the touch, as if an evil within is trying to escape.\""] = "This object feels wrong to the touch, as if an evil within is trying to escape." }, "Top Piece of Lord Valthalak's Amulet"},
    [22048] = {"瓦塔拉克饰品", "任务物品\n唯一\n使用: 瞄准瓦尔塔拉克领主的尸体，从护身符中灌输他的灵魂。\nReunited into its whole form, the amulet pulses strongly with the evil 精神 of Lord Valthalak.", "EpochHead 消耗品", "consumable", { ["Quest Item"] = "任务物品", ["Unique"] = "唯一", ["Use: Target Lord Valthalak's corpse to instill his spirit from the amulet."] = "使用: 瞄准瓦尔塔拉克领主的尸体，从护身符中灌输他的灵魂。", ["\"Reunited into its whole form, the amulet pulses strongly with the evil spirit of Lord Valthalak.\""] = "Reunited into its whole form, the amulet pulses strongly with the evil 精神 of Lord Valthalak." }, "Lord Valthalak's Amulet"},
