    [31518] = {"驱魔羽毛", "拾取后绑定\n唯一（5）\n使用：从目标鸦木叶须身上驱除寇寇之灵。尽快击杀这个灵魂，成功后叶须会被解救，并且不再具有攻击性。（1秒冷却）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique (5)"] = "唯一（5）", ["Use: Exorcises a Koi-Koi spirit from the targeted Raven's Wood Leafbeard. Slay the spirit as quickly as possible, for when you do, you will free the leafbeard and it will no longer be aggressive. (1 Sec Cooldown)"] = "使用：从目标鸦木叶须身上驱除寇寇之灵。尽快击杀这个灵魂，成功后叶须会被解救，并且不再具有攻击性。（1秒冷却）" }, "Exorcism Feather"},
    [31663] = {"灵魂召唤图腾", "任务物品\n唯一\n使用：在附近召唤一个召唤灵魂图腾，持续2分钟。如果小虚空龙在图腾周围 15 码内死亡，图腾将释放它的灵魂。 （5 秒冷却时间）", "EpochHead 消耗品", "consumable", { ["Quest Item"] = "任务物品", ["Unique"] = "唯一", ["Use: Summons a Spirit Calling Totem nearby, which lasts for 2 min. The totem will free the spirit of a lesser nether drake if it dies within 15 yards of the totem. (5 Sec Cooldown)"] = "使用：在附近召唤一个召唤灵魂图腾，持续2分钟。如果小虚空龙在图腾周围 15 码内死亡，图腾将释放它的灵魂。 （5 秒冷却时间）" }, "Spirit Calling Totems"},
