    [60405] = {"黑暗法师的龙杖", "拾取后绑定\n双手 102 - 191 伤害 (52.3 伤害 每秒) +15 耐力 +15 智力。\n需要等级 56\n物品等级 61\n装备：提高 伤害和治疗效果 done by magical 法术和effects by最多20. Equip: 恢复 5 法力值 per 5秒.\n你的 skin prickles when you hold this staff.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Two-Hand 102 - 191 Damage (52.3 damage per second) +15 Stamina +15 Intellect"] = "双手 102 - 191 伤害 (52.3 伤害 每秒) +15 耐力 +15 智力。", ["Requires Level 56"] = "需要等级 56", ["Item Level 61"] = "物品等级 61", ["Equip: Increases damage and healing done by magical spells and effects by up to 20. Equip: Restores 5 mana per 5 sec."] = "装备：提高 伤害和治疗效果 done by magical 法术和effects by最多20. Equip: 恢复 5 法力值 per 5秒.", ["\"Your skin prickles when you hold this staff.\""] = "你的 skin prickles when you hold this staff." }, "Darkmage's Dragonstaff"},
    [60406] = {"末日预言者袖口", "拾取后绑定\n手腕 37 护甲 +12 耐力 +11 智力。\n需要等级 56\n物品等级 61\n装备：提高 伤害和治疗效果 done by magical 法术和effects by最多10. Equip: 恢复 4 法力值 per 5秒.\nAccording to the Ogre calendar, the world will end on 19-TH-Red. Unfortunately no one knows when this is.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Wrist 37 Armor +12 Stamina +11 Intellect"] = "手腕 37 护甲 +12 耐力 +11 智力。", ["Requires Level 56"] = "需要等级 56", ["Item Level 61"] = "物品等级 61", ["Equip: Increases damage and healing done by magical spells and effects by up to 10. Equip: Restores 4 mana per 5 sec."] = "装备：提高 伤害和治疗效果 done by magical 法术和effects by最多10. Equip: 恢复 4 法力值 per 5秒.", ["\"According to the Ogre calendar, the world will end on 19-TH-Red. Unfortunately no one knows when this is.\""] = "According to the Ogre calendar, the world will end on 19-TH-Red. Unfortunately no one knows when this is." }, "Doomsayer's Cuffs"},
    [60407] = {"流水裹尸", "拾取后绑定\n背部 41 护甲 +14 力量。\n需要等级 56\n物品等级 61\n装备：+20 攻击强度\nHot和wet to the touch.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Back 41 Armor +14 Strength"] = "背部 41 护甲 +14 力量。", ["Requires Level 56"] = "需要等级 56", ["Item Level 61"] = "物品等级 61", ["Equip: +20 Attack Power."] = "装备：+20 攻击强度", ["\"Hot and wet to the touch.\""] = "Hot和wet to the touch." }, "Drool-Stained Shroud"},
    [60408] = {"带电龙鳞", "拾取后绑定\n饰品\n需要等级 56\n物品等级 61\n装备：剥取龙类时有几率获得额外的龙鳞。\nSlightly magnetic.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Trinket"] = "饰品", ["Requires Level 56"] = "需要等级 56", ["Item Level 61"] = "物品等级 61", ["Equip: Chance to gain additional Dragon Scales when skinning Dragons."] = "装备：剥取龙类时有几率获得额外的龙鳞。", ["\"Slightly magnetic.\""] = "Slightly magnetic." }, "Electrified Dragon Scale"},
