    [60769] = {"配方：邪石", "拾取后绑定\n需要 附魔 (300)\n使用：教你学会make a Felstone. Felstone。\n拾取后绑定\n唯一\n需要等级 50\n需要 附魔 (300)\n使用：用格罗姆博拉灵魂石标记你当前的户外位置，持续 4 小时。再次使用会摧毁标记并将你召回到该位置。（10秒冷却）\n需要 CorruptedDraenethystSphere,Demonic符文(12),Large卓越碎片(8),强效EternalEssence(8),AzerothianDiamond(4),DreamDust(20)", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Enchanting (300)"] = "需要 附魔 (300)", ["Use: Teaches you how to make a Felstone. Felstone"] = "使用：教你学会make a Felstone. Felstone。", ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Requires Level 50"] = "需要等级 50", ["Requires Enchanting (300)"] = "需要 附魔 (300)", ["Use: Mark your current overworld location for the next 4 hours using a Grombolar Soulstone. Use again to destroy the mark and recall yourself to its location. (10 Sec Cooldown)"] = "使用：用格罗姆博拉灵魂石标记你当前的户外位置，持续 4 小时。再次使用会摧毁标记并将你召回到该位置。（10秒冷却）", ["Requires Corrupted Draenethyst Sphere, Demonic Rune (12), Large Brilliant Shard (8), Greater Eternal Essence (8), Azerothian Diamond (4), Dream Dust (20)"] = "需要 CorruptedDraenethystSphere,Demonic符文(12),Large卓越碎片(8),强效EternalEssence(8),AzerothianDiamond(4),DreamDust(20)" }, "Formula: Felstone"},
    [60770] = {"Item 60770", "正在获取物品信息", "EpochHead 消耗品", "consumable", { ["Retrieving item information"] = "正在获取物品信息" }, "Item 60770"},
    [60772] = {"可疑炖菜", "需要等级 35\n使用：在 30秒 内恢复 1392 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，12 耐力和精神，持续 15分钟。\nIs that a finger?", "EpochHead 消耗品", "consumable", { ["Requires Level 35"] = "需要等级 35", ["Use: Restores 1392 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 12 Stamina and Spirit for 15 min."] = "使用：在 30秒 内恢复 1392 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，12 耐力和精神，持续 15分钟。", ["\"Is that a finger?\""] = "Is that a finger?" }, "Suspicious Stew"},
