    [60800] = {"强大匕首", "装备后绑定\n单手 31 - 59 伤害 (32.1 伤害 每秒) 51 护甲 +6 耐力。\n需要等级 37\n物品等级 42\n装备：防御等级提高 4。", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["One-Hand 31 - 59 Damage (32.1 damage per second) 51 Armor +6 Stamina"] = "单手 31 - 59 伤害 (32.1 伤害 每秒) 51 护甲 +6 耐力。", ["Requires Level 37"] = "需要等级 37", ["Item Level 42"] = "物品等级 42", ["Equip: Increased Defense +4."] = "装备：防御等级提高 4。" }, "Formidable Dagger"},
    [60801] = {"剥肉者", "装备后绑定\n单手 41 - 77 伤害 (32.8 伤害 每秒)。\n需要等级 38\n命中时有几率：造成 150% 的武器伤害，并使目标受到的治疗效果减少 10%，持续 15 秒。", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["One-Hand 41 - 77 Damage (32.8 damage per second)"] = "单手 41 - 77 伤害 (32.8 伤害 每秒)。", ["Requires Level 38"] = "需要等级 38", ["Chance on hit: Inflicts 150% weapon damage and reduces healing received by the target by 10% for 15 sec."] = "命中时有几率：造成 150% 的武器伤害，并使目标受到的治疗效果减少 10%，持续 15 秒。" }, "Fleshrender"},
