    [62202] = {"厚战士套件", "拾取后绑定\n使用：将护甲片永久嵌入你的裤子，使你的攻击强度提高 20 点。只能为制皮师的裤子附魔，嵌入后会使裤子变为灵魂绑定。（1秒冷却）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Use: Permanently embed an armor kit onto your pants, increasing your attack power by 20. Only the leatherworker's pants can be enchanted and embedding pants will cause it to become soulbound. (1 Sec Cooldown)"] = "使用：将护甲片永久嵌入你的裤子，使你的攻击强度提高 20 点。只能为制皮师的裤子附魔，嵌入后会使裤子变为灵魂绑定。（1秒冷却）" }, "Thick Warrior's Kit"},
    [62203] = {"厚保护器套件", "拾取后绑定\n使用：将护甲片永久嵌入你的裤子，使你的耐力提高 12 点。只能为制皮师的裤子附魔，嵌入后会使裤子变为灵魂绑定。（1秒冷却）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Use: Permanently embed an armor kit onto your pants, increasing your stamina by 12. Only the leatherworker's pants can be enchanted and embedding pants will cause it to become soulbound. (1 Sec Cooldown)"] = "使用：将护甲片永久嵌入你的裤子，使你的耐力提高 12 点。只能为制皮师的裤子附魔，嵌入后会使裤子变为灵魂绑定。（1秒冷却）" }, "Thick Protector's Kit"},
