    [65698] = {"哀叹之靴", "拾取后绑定\n脚 251 护甲 +13 力量 +10 敏捷 +13 耐力。\n需要等级 57\n物品等级 62\n装备：攻击强度提高 20 点。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Feet 251 Armor +13 Strength +10 Agility +13 Stamina"] = "脚 251 护甲 +13 力量 +10 敏捷 +13 耐力。", ["Requires Level 57"] = "需要等级 57", ["Item Level 62"] = "物品等级 62", ["Equip: Increases attack power by 20."] = "装备：攻击强度提高 20 点。" }, "Boots of Lamentation"},
    [65700] = {"吊饰项链", "拾取后绑定\n唯一\n颈部 60 护甲 +9 敏捷。\n需要等级 57\n物品等级 62\n装备：躲闪几率提高 1%。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Neck 60 Armor +9 Agility"] = "颈部 60 护甲 +9 敏捷。", ["Requires Level 57"] = "需要等级 57", ["Item Level 62"] = "物品等级 62", ["Equip: Increases your chance to dodge an attack by 1%."] = "装备：躲闪几率提高 1%。" }, "Charm Necklace"},
    [65701] = {"被啃咬的豺狼人", "拾取后绑定\n单手 66 - 142 伤害 (40.0 伤害 每秒) +12 力量 +5 火焰抗性。\n需要等级 56\n物品等级 61\nIt's raw.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["One-Hand 66 - 142 Damage (40.0 damage per second) +12 Strength +5 Fire Resistance"] = "单手 66 - 142 伤害 (40.0 伤害 每秒) +12 力量 +5 火焰抗性。", ["Requires Level 56"] = "需要等级 56", ["Item Level 61"] = "物品等级 61", ["\"It's raw.\""] = "It's raw." }, "Gnawed Gnoll"},
    [65703] = {"厨房短裙", "拾取后绑定\n腿部 150 护甲 +15 耐力 +15 智力 +8 精神。\n需要等级 56\n物品等级 61\n装备：所有魔法法术和效果的治疗效果最多提高 42 点，造成的伤害最多提高 13 点。\nCleans up accidents.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Legs 150 Armor +15 Stamina +15 Intellect +8 Spirit"] = "腿部 150 护甲 +15 耐力 +15 智力 +8 精神。", ["Requires Level 56"] = "需要等级 56", ["Item Level 61"] = "物品等级 61", ["Equip: Increases healing done by up to 42 and damage done by up to 13 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 42 点，造成的伤害最多提高 13 点。", ["\"Cleans up accidents.\""] = "Cleans up accidents." }, "Kitchen Kilt"},
