    [70000] = {"黑铁镐", "拾取后绑定\n唯一\nThis 物品 开始一个任务 主手 67 - 126 伤害 (34.5 伤害 每秒) +10 力量。\n需要等级 55\n物品等级 58\n需要 Thorium Brotherhood - Honored Equip: 采矿 +3", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["This Item Begins a Quest Main Hand 67 - 126 Damage (34.5 damage per second) +10 Strength"] = "This 物品 开始一个任务 主手 67 - 126 伤害 (34.5 伤害 每秒) +10 力量。", ["Requires Level 55"] = "需要等级 55", ["Item Level 58"] = "物品等级 58", ["Requires Thorium Brotherhood - Honored Equip: Mining +3"] = "需要 Thorium Brotherhood - Honored Equip: 采矿 +3" }, "Dark Iron Pick"},
    [70001] = {"老化镐升级底座", "拾取后绑定\n唯一\n需要等级 55\n使用：升级黑铁镐的底座和说明。上面写着你需要 20 块黑铁锭和 4 块奥金锭，为燃烧精华制作外壳和导流脉络。不需要锻造技能，但需要黑熔炉。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Requires Level 55"] = "需要等级 55", ["Use: Base and instructions for upgrading a Dark Iron Pick, it says you will need 20 Dark Iron Bars and 4 Arcanite Bars to build a housing and channeling vein for a Burning Essence. Smithing not required, however a Black Forge is."] = "使用：升级黑铁镐的底座和说明。上面写着你需要 20 块黑铁锭和 4 块奥金锭，为燃烧精华制作外壳和导流脉络。不需要锻造技能，但需要黑熔炉。" }, "Aged Pick Upgrade Base"},
    [70002] = {"火钢镐", "拾取后绑定\n唯一\n主手 77 - 145 伤害 +2 - 4 Fire 伤害 (40.7 伤害 每秒) +10 力量 +10 火焰抗性。\n需要等级 55\n物品等级 62\n装备：采矿 +5。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Main Hand 77 - 145 Damage +2 - 4 Fire Damage (40.7 damage per second) +10 Strength +10 Fire Resistance"] = "主手 77 - 145 伤害 +2 - 4 Fire 伤害 (40.7 伤害 每秒) +10 力量 +10 火焰抗性。", ["Requires Level 55"] = "需要等级 55", ["Item Level 62"] = "物品等级 62", ["Equip: Mining +5."] = "装备：采矿 +5。" }, "Burningsteel Pickaxe"},
    [90070] = {"元素显现", "使用后绑定\n唯一\n双手 277 - 451 Nature 伤害 (91.0 伤害 每秒) +27 力量 +27 敏捷。\n需要等级 60\n物品等级 84\n装备：Reduces 你的 几率 to be dodged or parried by 2%. Equip: Improves 你的 几率 to get a 爆击 with all 法术和attacks by 2%.\nThe skies are crying.", "EpochHead 消耗品", "consumable", { ["Binds when used"] = "使用后绑定", ["Unique"] = "唯一", ["Two-Hand 277 - 451 Nature Damage (91.0 damage per second) +27 Strength +27 Agility"] = "双手 277 - 451 Nature 伤害 (91.0 伤害 每秒) +27 力量 +27 敏捷。", ["Requires Level 60"] = "需要等级 60", ["Item Level 84"] = "物品等级 84", ["Equip: Reduces your chance to be dodged or parried by 2%. Equip: Improves your chance to get a critical strike with all spells and attacks by 2%."] = "装备：Reduces 你的 几率 to be dodged or parried by 2%. Equip: Improves 你的 几率 to get a 爆击 with all 法术和attacks by 2%.", ["\"The skies are crying.\""] = "The skies are crying." }, "Elemental Manifestation"},
    [90071] = {"吉利吉姆地雷", "吉利吉姆岛\n拾取后绑定\n唯一\n持续时间：7分钟\n使用：在地上放置一枚地雷。当敌对生物经过附近时，地雷会爆炸，造成 394 到 506 点火焰伤害并将其击退。地雷持续 2分钟。\n看起来足够稳定……？", "EpochHead 消耗品", "consumable", { ["Gillijim's Isle"] = "吉利吉姆岛", ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Duration: 7 min"] = "持续时间：7分钟", ["Use: Places a Land Mine on the ground. When a hostile creature passes near, It will explode for 394 to 506 fire damage and knock them away. The mine has a duration of 2 min."] = "使用：在地上放置一枚地雷。当敌对生物经过附近时，地雷会爆炸，造成 394 到 506 点火焰伤害并将其击退。地雷持续 2分钟。", ["\"Looks stable enough...?\""] = "看起来足够稳定……？" }, "Gillijim Land Mine"},
    [90072] = {"龙语空灵酊剂", "拾取后绑定\n唯一\n需要等级 60\n使用：抵消 80% 的所有法术伤害，持续 5 秒。\nSimply holding this flask makes you feel empty.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Requires Level 60"] = "需要等级 60", ["Use: Negates 80% of all spell damage for 5 sec."] = "使用：抵消 80% 的所有法术伤害，持续 5 秒。", ["\"Simply holding this flask makes you feel empty.\""] = "Simply holding this flask makes you feel empty." }, "Draconic Null Tincture"},
