    [90075] = {"蜂蜜黄油面包", "拾取后绑定\n需要等级 55\n使用：在 30秒 内恢复 2550 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，15 所有抗性，持续 6分钟。\n好吃到你根本不想和任何人分享。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Level 55"] = "需要等级 55", ["Use: Restores 2550 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 15 All Resistances for 6 minutes."] = "使用：在 30秒 内恢复 2550 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，15 所有抗性，持续 6分钟。", ["\"So good you don't even want to share it with anyone.\""] = "好吃到你根本不想和任何人分享。" }, "Honey Butter Bread"},
    [90076] = {"EZ-Thro“炸弹”", "吉利吉姆岛\n拾取后绑定\n唯一\n持续时间：4分钟\n使用：造成 132 到 218 点火焰伤害，并击退那个不幸的受害者……不管最后是谁。\nEZ-Thro 总部品质监控。", "EpochHead 消耗品", "consumable", { ["Gillijim's Isle"] = "吉利吉姆岛", ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Duration: 4 min"] = "持续时间：4分钟", ["Use: Inflicts 132 to 218 Fire damage and knocks the unfortunate victim away... Whoever that ends up being."] = "使用：造成 132 到 218 点火焰伤害，并击退那个不幸的受害者……不管最后是谁。", ["\"Quality controlled at EZ-Thro headquarters.\""] = "EZ-Thro 总部品质监控。" }, "EZ-Thro \"Da Bomba\""},
    [90077] = {"格罗姆斯血香", "任务物品\n使用: 前往冬泉谷部落老兵的安息之地致敬。", "EpochHead 消耗品", "consumable", { ["Quest Item"] = "任务物品", ["Use: Pay your respects at the resting place of the Horde veteran in Winterspring."] = "使用: 前往冬泉谷部落老兵的安息之地致敬。" }, "Gromsblood Incense"},
