    [90512] = {"木炭夹钳", "装备后绑定\n手 100 护甲 +15 耐力 +10 火焰抗性。\n需要等级 58\n物品等级 63\n装备：Improves 你的 几率 to 命中 with all 法术和attacks by 1%. Use: Absorbs 600 to 800 Fire 伤害. Lasts 30秒.（10分钟冷却）", "EpochHead 消耗品", "consumable", { ["Binds when equipped"] = "装备后绑定", ["Hands 100 Armor +15 Stamina +10 Fire Resistance"] = "手 100 护甲 +15 耐力 +10 火焰抗性。", ["Requires Level 58"] = "需要等级 58", ["Item Level 63"] = "物品等级 63", ["Equip: Improves your chance to hit with all spells and attacks by 1%. Use: Absorbs 600 to 800 Fire damage. Lasts 30 sec. (10 Min Cooldown)"] = "装备：Improves 你的 几率 to 命中 with all 法术和attacks by 1%. Use: Absorbs 600 to 800 Fire 伤害. Lasts 30秒.（10分钟冷却）" }, "Charcoal Grippers"},
    [90514] = {"红贝多", "拾取后绑定\n唯一\n-装备后 饰品 +13 耐力 +10 精神 +20 火焰抗性。\n需要等级 60\n需要 炼金术 (300) Equip: Improves your chance to get a critical strike with all spells and attacks by 1%. Equip: Restores 10 health per 5 sec. Equip: Increases the effect that healing potions have on the wearer by 40%. This effect does not stack.\nFirst stage of the Magnum Opus. This works as a Philosopher Stone for Alchemical Transmuations.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["-Equipped Trinket +13 Stamina +10 Spirit +20 Fire Resistance"] = "-装备后 饰品 +13 耐力 +10 精神 +20 火焰抗性。", ["Requires Level 60"] = "需要等级 60", ["Requires Alchemy (300) Equip: Improves your chance to get a critical strike with all spells and attacks by 1%. Equip: Restores 10 health per 5 sec. Equip: Increases the effect that healing potions have on the wearer by 40%. This effect does not stack."] = "需要 炼金术 (300) Equip: Improves your chance to get a critical strike with all spells and attacks by 1%. Equip: Restores 10 health per 5 sec. Equip: Increases the effect that healing potions have on the wearer by 40%. This effect does not stack.", ["\"First stage of the Magnum Opus. This works as a Philosopher Stone for Alchemical Transmuations.\""] = "First stage of the Magnum Opus. This works as a Philosopher Stone for Alchemical Transmuations." }, "Rubedo"},
    [90515] = {"强效熔岩之吻", "需要等级 45\n使用：在 30秒 内恢复 1392 点生命值。进食时必须保持坐姿。", "EpochHead 消耗品", "consumable", { ["Requires Level 45"] = "需要等级 45", ["Use: Restores 1392 health over 30 sec. Must remain seated while eating."] = "使用：在 30秒 内恢复 1392 点生命值。进食时必须保持坐姿。" }, "Greater Lava Kisser"},
    [90517] = {"火之权柄碎片", "需要等级 55\nIt looks similar to Elemental Fire, but there is something strange about it. Perhaps someone may be interested in it?", "EpochHead 消耗品", "consumable", { ["Requires Level 55"] = "需要等级 55", ["\"It looks similar to Elemental Fire, but there is something strange about it. Perhaps someone may be interested in it?\""] = "It looks similar to Elemental Fire, but there is something strange about it. Perhaps someone may be interested in it?" }, "Fragment of Fire's Authority"},
    [90518] = {"火焰微粒", "使用后绑定\n使用: 将十颗火焰微粒变成熔岩诱饵。", "EpochHead 消耗品", "consumable", { ["Binds when used"] = "使用后绑定", ["Use: Turn ten Motes of Flame into a Molten Lure."] = "使用: 将十颗火焰微粒变成熔岩诱饵。" }, "Mote of Flame"},
    [90519] = {"熔岩诱饵", "拾取后绑定\n使用: 涂抹在钓鱼竿上时，钓鱼能力提高 75 点，并且在熔岩或岩浆中钓鱼 10 分钟时有机会获得额外物品。 （10 秒冷却时间）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Use: When applied to your fishing pole, increases Fishing by 75 and you have a chance to obtain an extra item when fishing in lava or magma for 10 min. (10 Sec Cooldown)"] = "使用: 涂抹在钓鱼竿上时，钓鱼能力提高 75 点，并且在熔岩或岩浆中钓鱼 10 分钟时有机会获得额外物品。 （10 秒冷却时间）" }, "Molten Lure"},
    [90520] = {"抗火药水", "需要等级 32\n使用: 使你的火焰抗性提高 65 点，持续 3 分钟。 （2 分钟冷却时间）", "EpochHead 消耗品", "consumable", { ["Requires Level 32"] = "需要等级 32", ["Use: Increases your resistance to Fire by 65 for 3 min. (2 Min Cooldown)"] = "使用: 使你的火焰抗性提高 65 点，持续 3 分钟。 （2 分钟冷却时间）" }, "Fire Resistance Potion"},
